void insertionSort(int a[], int n) {
    for (int i = 1; i < n; i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) {   /* shift larger keys right */
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = key;
    }
}

int partition(int a[], int lo, int hi) {
    int pivot = a[hi], i = lo - 1, t;
    for (int j = lo; j < hi; j++)
        if (a[j] <= pivot) { i++; t = a[i]; a[i] = a[j]; a[j] = t; }
    t = a[i + 1]; a[i + 1] = a[hi]; a[hi] = t;
    return i + 1;                      /* final position of pivot */
}
void quickSort(int a[], int lo, int hi) {
    if (lo < hi) {
        int p = partition(a, lo, hi);
        quickSort(a, lo, p - 1);
        quickSort(a, p + 1, hi);
    }
}

void merge(int a[], int l, int m, int r) {
    int tmp[r - l + 1], i = l, j = m + 1, k = 0;
    while (i <= m && j <= r)
        tmp[k++] = (a[i] <= a[j]) ? a[i++] : a[j++];  /* <= keeps it stable */
    while (i <= m) tmp[k++] = a[i++];   while (j <= r) tmp[k++] = a[j++];
    for (k = 0; k < r - l + 1; k++) a[l + k] = tmp[k];
}
void mergeSort(int a[], int l, int r) {
    if (l < r) {
        int m = (l + r) / 2;
        mergeSort(a, l, m); mergeSort(a, m + 1, r);
        merge(a, l, m, r);
    }
}

void heapify(int a[], int n, int i) {
    int big = i, l = 2 * i + 1, r = 2 * i + 2, t;
    if (l < n && a[l] > a[big]) big = l;  if (r < n && a[r] > a[big]) big = r;
    if (big != i) {
        t = a[i]; a[i] = a[big]; a[big] = t;
        heapify(a, n, big);
    }
}
void heapSort(int a[], int n) {
    for (int i = n / 2 - 1; i >= 0; i--) heapify(a, n, i);  /* build max-heap */
    for (int i = n - 1; i > 0; i--) {
        int t = a[0]; a[0] = a[i]; a[i] = t;                /* max to the end */
        heapify(a, i, 0);
    }
}

int binarySearch(int a[], int n, int key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;   /* avoids overflow */
        if (a[mid] == key) return mid;
        else if (a[mid] < key) low = mid + 1;
        else high = mid - 1;
    }
    return -1;                              /* not found */
}

int adj[MAX][MAX], visited[MAX], n;     /* clear visited before each traversal */
void dfs(int u) {
    visited[u] = 1; visit(u);
    for (int v = 0; v < n; v++)
        if (adj[u][v] && !visited[v]) dfs(v);
}
void bfs(int s) {
    int q[MAX], front = 0, rear = 0;
    visited[s] = 1; q[rear++] = s;
    while (front < rear) {
        int u = q[front++]; visit(u);
        for (int v = 0; v < n; v++)
            if (adj[u][v] && !visited[v]) { visited[v] = 1; q[rear++] = v; }
    }
}

void warshall(int R[][MAX], int n) {   /* R starts as the adjacency matrix */
    for (int k = 0; k < n; k++)          /* k = allowed intermediate vertex */
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                R[i][j] = R[i][j] || (R[i][k] && R[k][j]);
}

void topoSort(int n) {               /* adj[][] and indeg[] already filled */
    int q[MAX], front = 0, rear = 0, count = 0;
    for (int v = 0; v < n; v++) if (indeg[v] == 0) q[rear++] = v;
    while (front < rear) {
        int u = q[front++]; order[count++] = u;
        for (int v = 0; v < n; v++)
            if (adj[u][v] && --indeg[v] == 0) q[rear++] = v;
    }
    if (count < n) reportCycle();      /* graph was not a DAG */
}

void dijkstra(int w[][MAX], int n, int s, int d[]) {   /* w = 0 means no edge */
    int done[MAX] = {0};
    for (int v = 0; v < n; v++) d[v] = INF;
    d[s] = 0;
    for (int it = 0; it < n; it++) {
        int u = -1;
        for (int v = 0; v < n; v++)                    /* nearest unsettled */
            if (!done[v] && (u == -1 || d[v] < d[u])) u = v;
        done[u] = 1;
        for (int v = 0; v < n; v++)                    /* relax edges of u */
            if (w[u][v] && d[u] + w[u][v] < d[v]) d[v] = d[u] + w[u][v];
    }
}
